{"file_path":"sales_dashboard/loader.py","content":""""Product analytics dashboard: session-log parsing and daily counts."""


def parse_session_log(lines):
    """Parse session log lines into session dictionaries.

    Blank lines, whitespace-only lines, and comment lines are ignored. Errors
    identify the original (1-based) input line number.
    """
    out = []
    for line_number, line in enumerate(lines, start=1):
        if not line.strip() or line.lstrip().startswith("#"):
            continue

        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected exactly three fields")

        id_, day_text, converted_text = fields
        try:
            day = int(day_text)
        except ValueError as error:
            raise ValueError(f"line {line_number}: day must be an integer") from error

        converted_values = {"1": True, "0": False, "": None}
        if converted_text not in converted_values:
            raise ValueError(f"line {line_number}: converted must be 1, 0, or empty")

        out.append({"id": id_, "day": day, "converted": converted_values[converted_text]})
    return out


def dedupe_sessions(events):
    """Keep the last record for each id and sort by day, then id."""
    latest = {}
    for event in events:
        latest[event["id"]] = event
    return sorted(latest.values(), key=lambda event: (event["day"], event["id"]))


def daily_conversion_counts(events, start_day, end_day):
    """Count converted sessions for each inclusive day in the requested range."""
    if end_day < start_day:
        return []

    counts = [0] * (end_day - start_day + 1)
    for event in events:
        day = event["day"]
        if start_day <= day <= end_day and event["converted"] is True:
            counts[day - start_day] += 1
    return counts
"}

{"file_path":"sales_dashboard/report.py","content":""""Product analytics dashboard: campaign and group reports."""
from sales_dashboard.loader import daily_conversion_counts
from sales_dashboard.metrics import pooled_conversion_rate, conversion_rate, conversions_in_window


def campaign_summary(groups, days):
    """Summarize pooled rate, recent conversions, and nonempty groups."""
    all_events = [event for events in groups.values() for event in events]
    if all_events:
        first_day = min(event["day"] for event in all_events)
        last_day = max(event["day"] for event in all_events)
        daily_counts = daily_conversion_counts(all_events, first_day, last_day)
        recent = conversions_in_window(daily_counts, days)
    else:
        recent = 0

    return {
        "rate": round(pooled_conversion_rate(groups), 3),
        "recent": recent,
        "groups": sum(bool(events) for events in groups.values()),
    }


def top_converting_groups(groups, n):
    """Return up to ``n`` nonempty groups by rate, then ascending name."""
    ranked = [
        group
        for group, events in groups.items()
        if events
    ]
    ranked.sort(key=lambda group: (-conversion_rate(groups[group]), group))
    return ranked[:n]
