{"file_path":"tests/test_metrics.py","content":"import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_basic():
    assert conversion_rate([{"converted": True}, {"converted": False}]) == 0.5


def test_conversion_rate_none_counts_as_not_converted():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5


def test_conversion_rate_empty():
    assert conversion_rate([]) == 0.0


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {
        "large": [{"converted": True}, {"converted": False}, {"converted": False}],
        "small": [{"converted": True}],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.5
    assert pooled_conversion_rate({}) == 0.0


def test_conversions_in_window():
    assert conversions_in_window([1, 2, 3, 4], 2) == 7
    assert conversions_in_window([1, 2], 5) == 3
    assert conversions_in_window([1, 2], 0) == 0


def test_parse_session_log_values_whitespace_and_skips():
    assert parse_session_log(
        ["  # comment", "", "  ", " x1 , 3 , 1 ", "x2,4,0", "x3,5,"]
    ) == [
        {"id": "x1", "day": 3, "converted": True},
        {"id": "x2", "day": 4, "converted": False},
        {"id": "x3", "day": 5, "converted": None},
    ]


def test_parse_session_log_errors_include_original_line_number():
    with pytest.raises(ValueError, match="line 2"):
        parse_session_log(["# comment", "bad,line"])
    with pytest.raises(ValueError, match="line 3"):
        parse_session_log(["", " # comment", "x,not-a-day,1"])


def test_dedupe_sessions_keeps_last_duplicate_id():
    first = {"id": "same", "day": 1, "converted": True}
    last = {"id": "same", "day": 3, "converted": False}
    other = {"id": "other", "day": 2, "converted": True}
    assert dedupe_sessions([first, other, last]) == [other, last]


def test_daily_conversion_counts_inclusive_range():
    events = [
        {"id": "a", "day": 1, "converted": True},
        {"id": "b", "day": 2, "converted": True},
        {"id": "c", "day": 2, "converted": None},
        {"id": "d", "day": 4, "converted": True},
    ]
    assert daily_conversion_counts(events, 1, 3) == [1, 1, 0]
    assert daily_conversion_counts(events, 4, 2) == []


def test_campaign_summary_uses_pooled_rate_recent_counts_and_nonempty_groups():
    groups = {
        "one": [
            {"id": "a", "day": 1, "converted": True},
            {"id": "b", "day": 3, "converted": False},
        ],
        "empty": [],
        "two": [{"id": "c", "day": 3, "converted": True}],
    }
    assert campaign_summary(groups, 1) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert campaign_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_metrics_sort_and_exclude_empty_groups():
    groups = {
        "z": [{"converted": True}],
        "a": [{"converted": True}],
        "empty": [],
        "middle": [{"converted": False}],
    }
    assert top_converting_groups(groups, 2) == ["a", "z"]
    assert conversion_rate_by_group(groups) == {
        "a": 1.0,
        "empty": None,
        "middle": 0.0,
        "z": 1.0,
    }


def test_longest_conversion_streak_resets_on_zero():
    assert longest_conversion_streak([1, 2, 0, 3, 0]) == 2
    assert longest_conversion_streak([]) == 0
